use serde_json::{json,Value};use std::collections::BTreeMap;
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Registration{pub registry:String,pub id:String,pub owner_mod:String,pub value_kind:String}
#[derive(Default)]pub struct RegistryStore{entries:BTreeMap<(String,String),Registration>}
pub struct RegistryTransaction{owner_mod:String,staged:Vec<Registration>}
impl RegistryTransaction{pub fn new(id:&str)->Result<Self,String>{if !valid_ns(id)||id.contains(':'){return Err("invalid_mod_id".into());}Ok(Self{owner_mod:id.into(),staged:Vec::new()})}pub fn register(&mut self,registry:&str,id:&str,kind:&str)->Result<(),String>{if !valid_ns(registry)||!valid_id(id)||kind.is_empty()||kind.len()>64{return Err("invalid_registration_descriptor".into());}let name=if id.contains(':'){id.into()}else{format!("{}:{id}",self.owner_mod)};if self.staged.iter().any(|v|v.registry==registry&&v.id==name){return Err("duplicate_id_in_transaction".into());}self.staged.push(Registration{registry:registry.into(),id:name,owner_mod:self.owner_mod.clone(),value_kind:kind.into()});Ok(())}pub fn commit(self,s:&mut RegistryStore)->Result<usize,String>{for v in &self.staged{if s.entries.contains_key(&(v.registry.clone(),v.id.clone())){return Err(format!("registry_conflict:{}:{}",v.registry,v.id));}}let n=self.staged.len();for v in self.staged{s.entries.insert((v.registry.clone(),v.id.clone()),v);}Ok(n)}}
impl RegistryStore{pub fn report(&self)->Value{json!({"mode":"transaction-staging-only","live_minecraft_registries_connected":false,"entries":self.entries.values().map(|v|json!({"registry":v.registry,"id":v.id,"owner_mod":v.owner_mod,"value_kind":v.value_kind})).collect::<Vec<_>>()})}}
fn valid_ns(v:&str)->bool{!v.is_empty()&&v.len()<=64&&v.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'))}fn valid_id(v:&str)->bool{if v.is_empty()||v.len()>256{return false;}let(ns,p)=v.split_once(':').unwrap_or(("",v));if v.contains(':')&&!valid_ns(ns){return false;}!p.is_empty()&&p.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'|b'/'))}
#[cfg(test)]mod tests{use super::*;#[test]fn registry_commits_are_atomic(){let mut s=RegistryStore::default();let mut a=RegistryTransaction::new("naturescompass").unwrap();a.register("item","natures_compass","item").unwrap();assert_eq!(a.commit(&mut s).unwrap(),1);let mut b=RegistryTransaction::new("othermod").unwrap();b.register("item","naturescompass:natures_compass","item").unwrap();b.register("item","second","item").unwrap();assert!(b.commit(&mut s).unwrap_err().starts_with("registry_conflict"));assert_eq!(s.entries.len(),1);}}
